-- GENERATED by scripts/gen-seed.ts from lib/engine/program.ts. Do not edit by hand.
on conflict (slug) do update set
  exercise_key = excluded.exercise_key,
  name = excluded.name,
  slot_day = excluded.slot_day,
  order_index = excluded.order_index,
  rest_seconds = excluded.rest_seconds,
  range_min = excluded.range_min,
  range_max = excluded.range_max,
  is_unilateral = excluded.is_unilateral,
  is_bodyweight = excluded.is_bodyweight,
  category = excluded.category,
  seed_weight = excluded.seed_weight,
  seed_reps = excluded.seed_reps,
  variant_rule = excluded.variant_rule,
  rep_unit = excluded.rep_unit;

-- Remove slots that no longer exist in the program.
delete from public.exercises where slug not in ('mon-incline-db-press', 'mon-flat-db-press', 'mon-db-pullover', 'mon-hanging-knee-raise', 'mon-anti-rotation-press', 'tue-pull-up', 'tue-single-arm-db-row', 'tue-chest-supported-db-row', 'tue-rear-delt-fly', 'tue-dead-bug', 'wed-goblet-squat', 'wed-db-rdl', 'wed-reverse-lunge', 'wed-single-leg-calf-raise', 'wed-db-hip-thrust', 'thu-press', 'thu-seated-db-oh-press', 'thu-overhead-db-extension', 'thu-hammer-curl', 'thu-lateral-raise', 'fri-pull-up', 'fri-bent-over-row', 'fri-db-rdl', 'fri-hanging-leg-raise', 'fri-seated-calf-raise');
